package app.tinyui

/** A throwaway 2048-bit key pair for the round trips; never a real one. */
internal object RsaTestKeys {
    /** X.509 SubjectPublicKeyInfo DER, base64: what pages pass. */
    const val PUBLIC = ""
    /** PKCS#8 PrivateKeyInfo DER, base64: what Java's KeyFactory reads. */
    const val PRIVATE_PKCS8 = ""
    /** PKCS#1 RSAPrivateKey DER, base64: what SecKeyCreateWithData reads. */
    const val PRIVATE_PKCS1 = ""
}
